        "seed": "Atividade: Repertório Acadêmico\n\nObjetivo: Organize conceitos, fontes e exemplos de Odontologia em repertório acadêmico.\n\nExemplo de estudo: Cariologia: Construa um quadro separando processo, lesão, severidade e atividade, com exemplos de informações necessárias para cada dimensão. No caderno, registre uma definição em suas palavras, um esquema das relações principais e uma pergunta de revisão sobre lesão cariosa e atividade. Releia o exemplo e explique quais observações sustentam a interpretação e quais informações ainda faltam.\n\nQuestão para orientação: quais evidências sustentam minha interpretação?\n\nPróxima ação: revisar o registro e relacioná-lo ao conteúdo da disciplina."
