        "seed": "Atividade: Idiomas e Leitura Técnica\n\nObjetivo: Organize vocabulário, leituras e prática de apresentação.\n\nExemplo de estudo: Prótese removível — Suporte, retenção e estabilidade: Monte diagramas de forças e classifique os componentes segundo suas contribuições predominantes, sem reduzir cada peça a uma única função exclusiva. No caderno, registre uma definição em suas palavras, um esquema das relações principais e uma pergunta de revisão sobre suporte, retenção e estabilidade. Releia o exemplo e explique quais observações sustentam a interpretação e quais informações ainda faltam.\n\nQuestão para orientação: quais evidências sustentam minha interpretação?\n\nPróxima ação: revisar o registro e relacioná-lo ao conteúdo da disciplina."
